'use strict';
(()=>{
const entry=document.createElement('section');entry.className='panel';entry.innerHTML='<h2>Автоматические аудитории — тест</h2><p>Проверьте разделение по активности на синтетических событиях. Состав реальных групп и клиентов не изменяется.</p><button class="outline" id="activity-open">Открыть тестовый расчёт</button>';audiencePage.querySelector('#audience-cards').before(entry);
const page=document.createElement('main');page.hidden=true;page.id='activity-page';page.innerHTML=`<div class="breadcrumb">Аудитории / Активность — тест</div><div class="heading"><div><h1>Автоматические аудитории</h1><p>Активные и пассивные получатели по тестовым событиям</p></div><button class="outline" id="act-refresh">Обновить расчёт</button></div><div class="demo"><b>Только тестовые аудитории</b><span>Клиенты и реальные аудитории не меняются. Эти группы недоступны для отправки; согласия и запреты в реальной базе сохраняются.</span></div>
<section class="panel"><h2>Источник и правила</h2><form id="act-form" class="act-grid"><label>Тестовые события<select id="act-source" aria-label="Источник активности"><option value="activity_demo">Демонстрация активности</option><option value="statistics">Тестовая статистика рассылок</option></select></label><label>Набор / рассылка<select id="act-campaign" aria-label="Рассылка активности"><option value="demo">Демонстрация статистики</option><option value="all">Все рассылки (тестовые события)</option></select></label><label>Период активности, дней<input id="act-lookback_days" type="number" min="1" max="730" value="90" required></label><label>Писем для пассивной аудитории, от<input id="act-min_delivered" type="number" min="1" max="20" value="3" required></label><label>Ожидание после доставки, дней<input id="act-quiet_days" type="number" min="0" max="180" value="7" required></label><label>На дату (пусто — сейчас)<input id="act-as_of" type="datetime-local"></label><button class="outline">Применить правила</button><button class="outline" type="button" id="act-defaults">Сбросить правила</button></form><p>Активный — есть переход в выбранном периоде. Пассивный — переходов нет, доставлено достаточно разных писем и выдержан срок после последней доставки. Открытия показываются отдельно и не заменяют переходы. Отписка и окончательная ошибка имеют приоритет.</p><p>Повторы доставки одного письма не увеличивают счётчик и не обновляют дату исходной доставки. В тестовой статистике одна рассылка считается одним письмом на получателя; в отдельной демонстрации используются идентификаторы писем.</p><p>Правила здесь тестовые, сохраняются только в этой вкладке. Расчёт обновляется каждые 15 секунд, пока страница открыта и поля правил не редактируются.</p><button class="outline" id="act-demo">Заполнить демонстрацию активности</button><p id="act-calculated"></p></section>
<section class="stats" id="act-cards" aria-label="Состав тестовых аудиторий"></section>
<section class="panel"><h2>Получатели и причины</h2><form id="act-filters" class="act-grid"><label>Аудитория<select id="act-state" aria-label="Аудитория активности"><option value="">Все</option><option value="active">Активные</option><option value="passive">Пассивные</option><option value="insufficient">Мало данных</option><option value="excluded">Исключены</option></select></label><label>Поиск email<input id="act-query" type="search"></label><button class="outline">Показать</button></form><div id="act-rows" class="table-scroll"></div><div class="actions"><button class="outline" id="act-prev">Назад</button><span id="act-pagination"></span><button class="outline" id="act-next">Далее</button></div><p id="act-note"></p></section>
<section class="panel"><details><summary>Добавить тестовое событие активности</summary><p>Событие попадёт только в отдельную демонстрацию активности, не в реальную базу и не в статистику рассылок. Добавьте переход пассивному получателю, чтобы проверить автоматическое изменение группы.</p><form id="act-event" class="act-grid"><label>Тестовый email<input name="recipient" type="email" maxlength="254" required placeholder="activity-passive@example.invalid"></label><label>Событие<select name="kind" aria-label="Новое событие активности"><option value="click">Переход</option><option value="delivered">Доставка</option><option value="open">Открытие</option><option value="unsubscribe">Отписка</option><option value="error">Ошибка</option></select></label><label id="act-message-label" hidden>Идентификатор письма<input name="message_key" maxlength="120" placeholder="letter-001"></label><label id="act-error-label" hidden>Вид ошибки<select name="error_type"><option value="temporary">Временная</option><option value="permanent">Окончательная</option></select></label><label>Время события (необязательно)<input name="occurred_at" type="datetime-local"></label><button class="outline">Добавить тестовое событие</button></form><p>Для повторов одной доставки оставьте тот же идентификатор письма. Открытие само по себе не сделает получателя активным.</p><p role="status" id="act-event-status"></p></details></section><p role="status" id="act-status"></p>`;document.body.append(page);
const style=document.createElement('style');style.textContent=`#activity-page label{display:block;margin:8px 0}#activity-page input,#activity-page select{display:block;width:100%;box-sizing:border-box}#activity-page button{width:auto;min-height:36px;flex:none}.act-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(190px,1fr));gap:12px;align-items:end}#activity-page td,#activity-page th{padding:12px;text-align:left}#activity-page .stats{grid-template-columns:repeat(auto-fit,minmax(170px,1fr))}#activity-page input:focus,#activity-page select:focus{outline:none;border-color:#6BAEE0;box-shadow:0 0 0 2px #0795e918}`;document.head.append(style);
const $=id=>document.getElementById('act-'+id),labels={active:'Активные',passive:'Пассивные',insufficient:'Мало данных',excluded:'Исключены'};
let edits=0;
let timer,dirty=false,loading=false,request=0,currentPage=1,sort='email',direction='asc',eventToken=null;
const ruleKeys=['lookback_days','min_delivered','quiet_days','as_of'];
function text(tag,value){const e=document.createElement(tag);e.textContent=value;return e;}
function params(){const result=new URLSearchParams({source:$('source').value,campaign_id:$('campaign').value,state:$('state').value,query:$('query').value,sort,direction,page:String(currentPage)});for(const key of ruleKeys)if($(key).value)result.set(key,$(key).value);return result;}
function remember(){try{sessionStorage.setItem('activity-test-filters',JSON.stringify(Object.fromEntries(params())));}catch{}}
async function campaigns(selected){const data=await api('/api/campaigns');const chosen=selected||$('campaign').value;$('campaign').replaceChildren(new Option('Демонстрация статистики','demo'),new Option('Все рассылки (тестовые события)','all'));for(const row of data.campaigns)$('campaign').add(new Option(row.name,String(row.id)));if(!['demo','all'].includes(chosen)&&!data.campaigns.some(r=>String(r.id)===chosen)){try{const row=await api('/api/campaigns/'+chosen);$('campaign').add(new Option(row.name,String(row.id)));}catch{}}$('campaign').value=[...$('campaign').options].some(o=>o.value===chosen)?chosen:'demo';}
function schedule(){clearTimeout(timer);if(!page.hidden)timer=setTimeout(()=>{if(!dirty&&!loading)load();else schedule();},15000);}
async function load(){const edit=edits,token=++request;clearTimeout(timer);loading=true;$('status').textContent='Расчёт по тестовым событиям…';$('campaign').disabled=$('source').value!=='statistics';try{const data=await api('/api/activity-audiences?'+params());if(token!==request||edit!==edits)return;dirty=false;remember();currentPage=data.pagination.page;$('calculated').textContent=`${data.label} · Получателей: ${data.total} · Событий: ${data.events} · Расчёт: ${new Date(data.calculated_at).toLocaleString('ru-RU',{timeZone:data.timezone})} · На дату: ${new Date(data.as_of).toLocaleString('ru-RU',{timeZone:data.timezone})} (${data.timezone})`;$('cards').replaceChildren();for(const [key,label]of Object.entries(labels)){const box=document.createElement('article');box.append(text('span',label),text('strong',String(data.counts[key])),text('small','Виртуальная аудитория · тест'));const choose=text('button','Посмотреть');choose.className='outline';choose.onclick=()=>{$('state').value=key;currentPage=1;load();};box.append(choose);$('cards').append(box);}
 $('rows').replaceChildren();if(!data.recipients.length)$('rows').textContent='Нет получателей. Заполните демонстрацию или измените фильтры.';else{const table=document.createElement('table'),head=document.createElement('tr');for(const [key,label]of [['email','Email'],['state','Аудитория'],['','Причина'],['delivered','Разных писем доставлено'],['opens','Открытий (событий)'],['clicks','Переходов (событий)'],['last_delivery','Последняя доставка'],['last_click','Последний переход']]){const th=document.createElement('th');if(key){const button=text('button',label+(sort===key?(direction==='asc'?' ↑':' ↓'):' ↕'));button.onclick=()=>{direction=sort===key?(direction==='asc'?'desc':'asc'):'asc';sort=key;currentPage=1;load();};th.append(button);}else th.textContent=label;head.append(th);}table.append(head);for(const row of data.recipients){const tr=document.createElement('tr');for(const value of [row.email,row.label,row.reason,row.delivered,row.opens,row.clicks,row.last_delivery?new Date(row.last_delivery).toLocaleString('ru-RU',{timeZone:data.timezone}):'—',row.last_click?new Date(row.last_click).toLocaleString('ru-RU',{timeZone:data.timezone}):'—'])tr.append(text('td',String(value)));table.append(tr);}$('rows').append(table);}$('pagination').textContent=`${data.pagination.page} / ${data.pagination.pages} · в выборке: ${data.pagination.total}`;$('prev').disabled=!data.pagination.has_previous;$('next').disabled=!data.pagination.has_next;$('note').textContent=data.note;$('status').textContent='';}catch(e){if(token===request){$('status').textContent=e.message;$('cards').replaceChildren();$('rows').replaceChildren();$('calculated').textContent='';$('pagination').textContent='';}}finally{if(token===request){loading=false;schedule();}}}
$('form').oninput=()=>{edits++;dirty=true;$('status').textContent='Правила изменены. Нажмите «Применить правила» для нового расчёта.';};$('form').onsubmit=e=>{e.preventDefault();currentPage=1;load();};$('source').onchange=()=>{$('state').value='';$('query').value='';currentPage=1;load();};$('campaign').onchange=()=>{currentPage=1;load();};$('filters').onsubmit=e=>{e.preventDefault();currentPage=1;load();};$('refresh').onclick=load;$('defaults').onclick=()=>{for(const [key,value]of Object.entries({lookback_days:90,min_delivered:3,quiet_days:7,as_of:''}))$(key).value=value;currentPage=1;load();};$('prev').onclick=()=>{currentPage=Math.max(1,currentPage-1);load();};$('next').onclick=()=>{currentPage++;load();};
$('demo').onclick=async()=>{const b=$('demo');b.disabled=true;try{await api('/api/activity-audiences/demo',{method:'POST',headers:{'Content-Type':'application/json'},body:'{}'});$('source').value='activity_demo';$('state').value='';$('query').value='';currentPage=1;await load();$('status').textContent='Отдельный тестовый набор готов. Реальная база и статистика рассылок не менялись.';}catch(e){$('status').textContent=e.message;}finally{b.disabled=false;}};
const form=$('event');function eventFields(){$('message-label').hidden=form.elements.kind.value!=='delivered';$('error-label').hidden=form.elements.kind.value!=='error';form.elements.message_key.required=form.elements.kind.value==='delivered';}form.oninput=()=>{eventToken=null;};form.onchange=()=>{eventToken=null;eventFields();};form.onsubmit=async e=>{e.preventDefault();const b=form.querySelector('button');b.disabled=true;try{const values=Object.fromEntries(new FormData(form));if(values.kind!=='error')values.error_type='';if(values.kind!=='delivered')values.message_key='';eventToken=eventToken||crypto.randomUUID();await api('/api/activity-audiences/test-events',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...values,event_id:eventToken,test_only:true})});eventToken=null;$('source').value='activity_demo';$('state').value='';$('query').value=values.recipient;currentPage=1;await load();$('event-status').textContent='Тестовое событие сохранено. Группа получателя пересчитана; реальные контакты не изменены.';}catch(e){$('event-status').textContent=e.message;}finally{b.disabled=false;}};eventFields();
async function open(source,campaign,state,restore=false){for(const key of ['statistics-open','campaigns-open','subscriptions-open','templates-open'])try{sessionStorage.removeItem(key);}catch{}document.querySelectorAll('body>main').forEach(p=>p.hidden=true);page.hidden=false;document.querySelectorAll('aside nav button').forEach(b=>{b.classList.remove('active');b.removeAttribute('aria-current');});audiencesButton.classList.add('active');audiencesButton.setAttribute('aria-current','page');document.title='Автоматические аудитории — тест';if(source){$('source').value=source;if(!restore){$('query').value='';$('state').value='';currentPage=1;}}if(state!==undefined)$('state').value=state;try{sessionStorage.setItem('activity-test-open','1');await campaigns(campaign);await load();}catch(e){$('status').textContent=e.message;}}
document.getElementById('activity-open').onclick=()=>open();
window.ActivityAudiences={open};document.querySelector('aside nav').addEventListener('click',event=>{if(!event.target.closest('button:not(:disabled)'))return;page.hidden=true;clearTimeout(timer);try{sessionStorage.removeItem('activity-test-open');}catch{}});
try{const saved=JSON.parse(sessionStorage.getItem('activity-test-filters')||'null');if(saved){for(const key of ['source','state','query',...ruleKeys])if(typeof saved[key]==='string')$(key).value=saved[key];if(typeof saved.sort==='string')sort=saved.sort;if(typeof saved.direction==='string')direction=saved.direction;}if(sessionStorage.getItem('activity-test-open')==='1')open(saved?.source,saved?.campaign_id,saved?.state,true);}catch{}
})();
